svg.script:
const NS = "http://www.w3.org/2000/svg", W = 650, H = 400;
const L = 20, K = 7, D = 420;
const svg = document.documentElement;
const trailG = document.getElementById("trail"), liveG = document.getElementById("live"), knob = document.getElementById("knob");

let T = 1, targetT = 1;
let tip, cands = [], main = null, chosen = 0, stepStart = 0, steps = 0, sentenceLen = 30;
let paused = false, resumeAt = 0;
const trail = [], ghosts = [];

function el(tag, attrs, parent) {
  const e = document.createElementNS(NS, tag);
  for (const k in attrs) e.setAttribute(k, attrs[k]);
  parent.appendChild(e);
  return e;
}

function startSentence(x, y, now) {
  tip = { x, y, a: Math.random() * 6.283 };
  steps = 0;
  sentenceLen = 22 + Math.floor(Math.random() * 26);
  newStep(now);
}

function newStep(now) {
  const { x, y, a } = tip;
  const ca = Math.atan2(H / 2 - y, W / 2 - x);
  const edge = Math.min(1.5, Math.max(0, 1 - Math.min(x - 30, W - 30 - x, y - 30, H - 30 - y) / 70));
  const cx = x + Math.cos(a) * L / 2, cy = y + Math.sin(a) * L / 2;

  // Score each possible next step, then turn scores into probabilities at temperature T
  const raw = [];
  for (let i = 0; i < K; i++) {
    const o = -1.1 + 2.2 * i / (K - 1);
    const na = a + o + (Math.random() - 0.5) * 0.15;
    const score = -o * o * 3 + (Math.random() - 0.5) * 1.6 + edge * 3 * Math.cos(na - ca);
    raw.push({ na, score });
  }
  const mx = Math.max(...raw.map(r => r.score / T));
  let sum = 0;
  raw.forEach(r => { r.w = Math.exp(r.score / T - mx); sum += r.w; });
  raw.forEach(r => r.p = r.w / sum);
  const pmax = Math.max(...raw.map(r => r.p));

  let pick = Math.random(), acc = 0;
  chosen = K - 1;
  for (let i = 0; i < K; i++) { acc += raw[i].p; if (pick <= acc) { chosen = i; break; } }

  cands = raw.map(r => {
    const ex = x + Math.cos(r.na) * L, ey = y + Math.sin(r.na) * L;
    const d = `M${x.toFixed(1)} ${y.toFixed(1)} Q${cx.toFixed(1)} ${cy.toFixed(1)} ${ex.toFixed(1)} ${ey.toFixed(1)}`;
    const e = el("path", { class: "cand", d, pathLength: 1, "stroke-dasharray": "1 2", "stroke-dashoffset": 1 }, liveG);
    return { el: e, d, ex, ey, cx, cy, op: 0.06 + 0.7 * r.p / pmax };
  });
  const c = cands[chosen];
  main = el("path", { class: "main", d: c.d, pathLength: 1, "stroke-dasharray": "1 2", "stroke-dashoffset": 1 }, trailG);
  stepStart = now;
}

function retireCands(now) {
  cands.forEach(c => ghosts.push({ el: c.el, t0: now, op: c.op }));
  cands = [];
}

function endSentence(now) {
  if (steps > 0) {
    const dot = el("circle", { class: "period", cx: tip.x.toFixed(1), cy: tip.y.toFixed(1), r: 3 }, trailG);
    trail.push({ el: dot, born: now });
  }
}

function frame(now) {
  T += (targetT - T) * 0.05;
  knob.setAttribute("cy", (376 - (T - 0.25) / 2.35 * 352).toFixed(1));

  if (paused) {
    if (now >= resumeAt) { paused = false; startSentence(80 + Math.random() * (W - 160), 70 + Math.random() * (H - 140), now); }
  } else {
    const u = (now - stepStart) / D;
    cands.forEach(c => {
      c.el.setAttribute("stroke-dashoffset", (1 - Math.min(1, u * 1.8)).toFixed(3));
      c.el.setAttribute("stroke-opacity", c.op.toFixed(2));
    });
    main.setAttribute("stroke-dashoffset", (1 - Math.min(1, Math.max(0, (u - 0.5) / 0.5))).toFixed(3));

    if (u >= 1) {
      const c = cands[chosen];
      main.removeAttribute("stroke-dasharray");
      main.removeAttribute("stroke-dashoffset");
      trail.push({ el: main, born: now });
      retireCands(now);
      tip = { x: c.ex, y: c.ey, a: Math.atan2(c.ey - c.cy, c.ex - c.cx) };
      steps++;
      if (steps >= sentenceLen) { endSentence(now); paused = true; resumeAt = now + 1000; }
      else newStep(now);
    }
  }

  for (let i = ghosts.length - 1; i >= 0; i--) {
    const g = ghosts[i], f = 1 - (now - g.t0) / 1100;
    if (f <= 0) { g.el.remove(); ghosts.splice(i, 1); }
    else g.el.setAttribute("stroke-opacity", (g.op * f).toFixed(3));
  }
  for (let i = trail.length - 1; i >= 0; i--) {
    const t = trail[i], f = 1 - (now - t.born) / 22000;
    if (f <= 0) { t.el.remove(); trail.splice(i, 1); }
    else t.el.setAttribute("opacity", f.toFixed(3));
  }
  requestAnimationFrame(frame);
}

function toSvg(ev) {
  const pt = svg.createSVGPoint();
  pt.x = ev.clientX; pt.y = ev.clientY;
  return pt.matrixTransform(svg.getScreenCTM().inverse());
}

svg.addEventListener("pointermove", ev => {
  const p = toSvg(ev);
  targetT = 0.25 + Math.min(1, Math.max(0, (376 - p.y) / 352)) * 2.35;
});
svg.addEventListener("pointerleave", () => { targetT = 1; });
svg.addEventListener("click", ev => {
  const p = toSvg(ev), now = performance.now();
  if (!paused) {
    endSentence(now);
    retireCands(now);
    if (main) main.remove();
  }
  paused = false;
  startSentence(Math.min(W - 30, Math.max(30, p.x)), Math.min(H - 30, Math.max(30, p.y)), now);
});

startSentence(120, 200, performance.now());
requestAnimationFrame(frame);
